# Operating record FY1998-FY2026 from the 10-Ks (selected data and income statements, $M; the latest filed figure for each year)
rev = {1998:0.002,1999:1.019,2000:13.362,2001:53.437,2002:30.429,2003:22.084,2004:19.603,2005:20.428,2006:22.564,2007:22.473,2008:30.107,2009:33.219,2010:29.877,2011:44.065,2012:43.364,2013:58.889,2014:70.262,2015:75.913,2016:69.375,2017:58.215,2018:61.307,2019:67.2,2020:72.7,2021:78.3,2022:92.0,2023:98.0,2024:92.8,2025:88.431,2026:91.136}
oi = {1998:-0.882,1999:-11.300,2000:-69.716,2001:-105.224,2002:-115.130,2003:-11.620,2004:-4.404,2005:0.212,2006:0.095,2007:-6.468,2008:-2.614,2009:3.256,2010:1.222,2011:9.692,2012:-2.033,2013:1.243,2014:-4.059,2015:-11.286,2016:-5.873,2017:-3.725,2018:-0.988,2019:5.5,2020:7.4,2021:7.3,2022:-2.1,2023:1.4,2024:6.0,2025:4.433,2026:7.965}
# companyfacts values 2019-2024 (one decimal) cross-checked below against the faces
print('FY    revenue   op.inc   margin  cumulative-from-FY2003')
cum=0
for y in sorted(rev):
    if y>=2003: cum+=oi[y]
    print(f'{y} {rev[y]:8.1f} {oi[y]:8.1f} {100*oi[y]/rev[y] if rev[y]>1 else float("nan"):7.1f}%  {cum if y>=2003 else float("nan"):8.1f}')
for a,b in ((2003,2026),(2009,2026),(2017,2026),(2019,2026),(2022,2026)):
    s=sum(oi[y] for y in range(a,b+1)); r=sum(rev[y] for y in range(a,b+1))
    print(f'FY{a}-FY{b}: operating income {s:6.1f} on revenue {r:7.1f} = {100*s/r:4.1f}%; years positive {sum(1 for y in range(a,b+1) if oi[y]>0)} of {b-a+1}')
# owner earnings: OCF - SBC (incl. the FY2026 warrant for services) - (c)
ocf={2010:2.495,2011:6.782,2012:1.001,2013:10.025,2014:-4.659,2015:-10.503,2016:1.867,2017:5.401,2018:6.591,2019:6.954,2020:14.058,2021:13.862,2022:8.121,2023:4.621,2024:12.454,2025:5.263,2026:21.150}
sbc={2010:0.244,2011:0.218,2012:0.856,2013:1.081,2014:1.527,2015:2.317,2016:1.188,2017:0.667,2018:1.695,2019:1.623,2020:1.861,2021:1.700,2022:11.380,2023:6.246,2024:4.529,2025:2.449,2026:2.802+1.350}
capex={2010:0.521,2011:0.725,2012:1.827,2013:2.465,2014:1.772,2015:0.741,2016:0.547,2017:0.492,2018:0.137,2019:0.398,2020:0.514,2021:0.402,2022:0.628,2023:0.288,2024:0.198,2025:0.565,2026:0.617}
dep={2010:0.6,2011:0.6,2012:0.8,2013:1.3,2014:2.1-0.0,2015:2.5,2016:2.1,2017:1.1,2018:0.6,2019:0.4,2020:0.304,2021:0.428,2022:0.4,2023:0.35,2024:0.3,2025:0.340,2026:0.388}
dr={2010:-0.027,2011:1.794,2012:2.313,2013:11.720,2014:-6.558,2015:-1.566,2016:0.825,2017:7.711,2018:2.876,2019:13.673,2020:5.272,2021:6.682,2022:1.599,2023:-0.060,2024:-0.578,2025:0.329,2026:-1.584}
ar={2010:1.089,2011:-5.261,2012:1.350,2013:-6.147,2014:1.542,2015:-0.116,2016:-0.272,2017:4.209,2018:-0.130,2019:-13.270,2020:-2.882,2021:-2.767,2022:-2.247,2023:-4.508,2024:-0.261,2025:-0.437,2026:8.026}
cap_m=5.67*26171467/1e6
print(f'\ncap {cap_m:.1f}  (5.67 x 26,171,467)')
print('FY    OCF    SBC  capex  dep   defrev  AR   | OE capex end  OE dep end | OE ex defrev&AR swings (capex end)')
oe_c={};oe_d={}
for y in sorted(ocf):
    oe_c[y]=ocf[y]-sbc[y]-capex[y]; oe_d[y]=ocf[y]-sbc[y]-dep[y]
    print(f'{y} {ocf[y]:6.2f} {sbc[y]:5.2f} {capex[y]:5.2f} {dep[y]:5.2f} {dr[y]:6.2f} {ar[y]:6.2f} | {oe_c[y]:7.2f} {oe_d[y]:7.2f} | {oe_c[y]-dr[y]-ar[y]:7.2f}')
def w(d,n,end=2026): ys=range(end-n+1,end+1); return sum(d[y] for y in ys)/n
print('\nwindow  capex end (yield)   dep end (yield)')
for n in (1,2,3,4,5,7,10,15,17):
    a=w(oe_c,n); b=w(oe_d,n); print(f'{n:2d}y FY{2026-n+1}-26 {a:6.2f} ({100*a/cap_m:5.2f}%) {b:6.2f} ({100*b/cap_m:5.2f}%)')
print('rolling 5y (capex end / dep end):')
for e in range(2014,2027): print(f'  FY{e-4}-{e}: {w(oe_c,5,e):6.2f} / {w(oe_d,5,e):6.2f}')
print('\nFY2026 without the AR release (+8.026): capex end', round(oe_c[2026]-ar[2026],2))
print('sum OE capex end FY2010-26', round(sum(oe_c.values()),1), ' FY2017-26', round(sum(oe_c[y] for y in range(2017,2027)),1))
print('SBC+warrant as % of OCF FY2022-26', round(100*sum(sbc[y] for y in range(2022,2027))/sum(ocf[y] for y in range(2022,2027)),1))
print('deferred revenue change FY2017-21', round(sum(dr[y] for y in range(2017,2022)),1), 'FY2022-26', round(sum(dr[y] for y in range(2022,2027)),2))
print('FY2021 defrev/OCF', round(100*dr[2021]/ocf[2021],1))
